ruleExplore.bookList:
@js:(function(){
  var j = (typeof result === 'string') ? JSON.parse(result) : result;
  var out = [];
  var items = j.items || [];
  for (var i=0; i<items.length; i++) {
    var ent = items[i].entity || {};
    var tr = (ent.track_wrapper && ent.track_wrapper.track) || ent.track || {};
    if (!tr.id) continue;
    var album = tr.album || {};
    var arts = (tr.artists || []);
    var an = []; for (var a=0; a<arts.length; a++) an.push(arts[a].name||'');
    var cov = '';
    var uc = album.url_cover || {};
    if (uc.urls && uc.urls.length) cov = uc.urls[0] + (uc.uri||'');
    out.push({
      name: tr.name || '',
      author: an.join('/'),
      coverUrl: cov,
      detail: 'https://www.qishui.com/song/' + tr.id + '?trackId=' + tr.id,
      lastChapter: '时长' + Math.round((tr.duration||0)/1000) + '秒'
    });
  }
  return out;
})()

