ruleContent.content:
@js:(function(){
  var baseUrl = java.baseUrl || '';
  var trackId = '';
  var m = String(baseUrl).match(/trackId=([^&]+)/);
  if (m) trackId = m[1];
  if (!trackId) return '';
  var seoUrl = 'https://beta-luna.douyin.com/luna/h5/seo_track?track_id=' + trackId + '&device_platform=web';
  var seoOpt = { headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/134.0.0.0 Safari/537.36', 'Referer': 'https://www.douyin.com/' } };
  var seo = java.ajax(seoUrl + ',' + JSON.stringify(seoOpt));
  var sj = JSON.parse(seo);
  var pu = sj.track_player && sj.track_player.url_player_info || '';
  if (!pu) return '';
  var puOpt = { headers: { 'User-Agent': 'Mozilla/5.0', 'Referer': 'https://www.douyin.com/' } };
  var info = java.ajax(pu + ',' + JSON.stringify(puOpt));
  var ij = JSON.parse(info);
  var pl = ij.Result && ij.Result.Data && ij.Result.Data.PlayInfoList || [];
  var best = '';
  for (var i=0; i<pl.length; i++) {
    if (pl[i].MainPlayUrl && (!best || pl[i].Quality === 'highest' || pl[i].Quality === 'higher')) {
      best = pl[i].MainPlayUrl;
      if (pl[i].Quality === 'highest') break;
    }
  }
  return best;
})()

